        match self {
            Reg::Acc => RegClass::Acc,
            Reg::Ext => RegClass::Ext,
            Reg::Xr1 => RegClass::Xr,
            Reg::Xr2 => RegClass::Xr,
            Reg::Xr3 => RegClass::Fp,
            Reg::Iar => RegClass::Pc,
        }
    }
}

