            Reg::Acc => 0,
            Reg::Ext => 1,
            Reg::Xr1 => 2,
            Reg::Xr2 => 3,
            Reg::Xr3 => 4,
            Reg::Iar => 5,
        }
    }

    fn name(self) -> &'static str {
        Reg::name(self)
    }
}

