//! `sw-ibm1130-isa`: ISA description for IBM 1130.
//!
//! Generated by gen-isa from `gen-isa/docs/spec-examples/ibm1130.toml`,
//! with hand-added `addr_mode` and `branch_cond` modules ported from
//! `sw-comp-history/ibm-1130-rs` (MIT). Trait surface:
//! `sw_isa_core::Architecture`.
//!
//! Re-running the scaffolder will overwrite this file; re-add the two
//! `pub mod` lines marked HAND-ADDED below if regenerating.

pub mod branch;
pub mod decode;
pub mod encode;
pub mod opcode;
pub mod register;

// HAND-ADDED (not spec-driven; ported from ibm-1130-rs).
pub mod addr_mode;
pub mod branch_cond;

pub use addr_mode::AddressingMode;
pub use branch_cond::BranchCondition;
pub use opcode::Opcode;
pub use register::{Reg, parse_register};

/// Newtype address; arithmetic is in address-units (see
/// `Architecture::ADDRESS_UNIT`), not bytes.
#[derive(Copy, Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
pub struct Addr(pub u32);

impl sw_isa_core::address::AddressType for Addr {
    fn to_u64(self) -> u64 {
        self.0 as u64
    }
    fn from_u64(v: u64) -> Self {
        Addr(v as u32)
    }
    fn step(self, n: i64) -> Self {
        Addr((self.0 as i64 + n) as u32)
    }
}

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub struct Ibm1130;

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub enum Instruction {
    Short {
        op: Opcode,
        tag: u8,
        disp: i8,
    },
    Long {
        op: Opcode,
        tag: u8,
        indirect: bool,
        address: u16,
    },
}

impl sw_isa_core::Architecture for Ibm1130 {
    type Opcode = opcode::Opcode;
    type Register = register::Reg;
    type Instruction = Instruction;
    type Address = Addr;
    type Format = sw_isa_core::format::Length;

    const NAME: &'static str = "IBM 1130";
    const ENDIAN: sw_isa_core::endian::Endian = sw_isa_core::endian::Endian::Big;
    const ADDRESS_UNIT: sw_isa_core::address::AddressUnit =
        sw_isa_core::address::AddressUnit::Word16;
    const WORD_BITS: u32 = 16;
    const MIN_INSTR_BYTES: usize = 2;
    const MAX_INSTR_BYTES: usize = 4;

    fn decode(
        bytes: &[u8],
        _pc: Self::Address,
    ) -> Result<(Self::Instruction, usize), sw_isa_core::DecodeError> {
        decode::decode(bytes)
    }

    fn encode(insn: &Self::Instruction, out: &mut [u8]) -> Result<usize, sw_isa_core::EncodeError> {
        encode::encode(insn, out)
    }

    fn disassemble(insn: &Self::Instruction, w: &mut dyn core::fmt::Write) -> core::fmt::Result {
        match insn {
            Instruction::Short { op, tag, disp } => {
                write!(w, "<Short op={:?} tag={:?} disp={:?}>", op, tag, disp)
            }
            Instruction::Long {
                op,
                tag,
                indirect,
                address,
            } => write!(
                w,
                "<Long op={:?} tag={:?} indirect={:?} address={:?}>",
                op, tag, indirect, address
            ),
        }
    }
}

