const RESERVED: &[Reg] = &[Reg::Ext, Reg::Xr2, Reg::Xr3, Reg::Iar];
const FIXED_PAIRS: &[(Reg, Reg)] = &[(Reg::Acc, Reg::Ext)];

impl RegisterClasses<Ibm1130> for Ibm1130RegClasses {
    fn gpr() -> &'static [Reg] {
        GPR
    }

    fn reserved() -> &'static [Reg] {
        RESERVED
    }

    fn fixed_pairs() -> &'static [(Reg, Reg)] {
        FIXED_PAIRS
    }
}

